<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>URN Studio — Mon affiche d'adhésion</title>
<meta property="og:type" content="website">
<meta property="og:title" content="Créez votre affiche J'adhère à l'URN">
<meta property="og:description" content="Union pour le Réveil National">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700;800&display=swap" rel="stylesheet">
<style>
  :root{
    --orange:#F07818;
    --orange-deep:#D96410;
    --green:#0B4A26;
    --green-ink:#06301A;
    --cream:#FBF8F3;
    --line:#E8E0D4;
    --shadow:0 10px 30px rgba(6,48,26,.14);
  }
  *{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}
  body{
    font-family:'Poppins',system-ui,sans-serif;
    background:var(--cream);
    color:var(--green-ink);
    min-height:100vh;
    display:flex;flex-direction:column;align-items:center;
  }
  header{
    width:100%;
    background:var(--green);
    color:#fff;
    padding:18px 20px 22px;
    text-align:center;
    border-bottom:5px solid var(--orange);
  }
  header h1{font-size:1.15rem;font-weight:800;letter-spacing:.5px}
  header h1 span{color:#FFB067}
  header p{font-size:.8rem;opacity:.85;font-weight:400;margin-top:2px}
  main{
    width:100%;max-width:480px;
    padding:20px 16px 40px;
    display:flex;flex-direction:column;gap:16px;
  }
  .poster-wrap{
    position:relative;
    border-radius:16px;
    overflow:hidden;
    box-shadow:var(--shadow);
    background:#fff;
    touch-action:none;
  }
  canvas{display:block;width:100%;height:auto}
  .hint{
    position:absolute;inset:auto 0 12px 0;
    display:flex;justify-content:center;
    pointer-events:none;
    opacity:0;transition:opacity .3s;
  }
  .hint.show{opacity:1}
  .hint span{
    background:rgba(6,48,26,.85);color:#fff;
    font-size:.75rem;font-weight:600;
    padding:8px 16px;border-radius:100px;
    backdrop-filter:blur(4px);
  }
  .controls{display:flex;flex-direction:column;gap:12px}
  .btn{
    display:flex;align-items:center;justify-content:center;gap:10px;
    width:100%;padding:16px;
    border:none;border-radius:14px;
    font-family:inherit;font-size:1rem;font-weight:700;
    cursor:pointer;
    transition:transform .1s, box-shadow .2s;
  }
  .btn:active{transform:scale(.98)}
  .btn-orange{
    background:var(--orange);color:#fff;
    box-shadow:0 6px 18px rgba(240,120,24,.35);
  }
  .btn-orange:hover{background:var(--orange-deep)}
  .btn-green{
    background:var(--green);color:#fff;
    box-shadow:0 6px 18px rgba(11,74,38,.3);
  }
  .btn-green[disabled]{opacity:.35;cursor:not-allowed;box-shadow:none}
  .btn svg{flex:none}
  .zoom-row{
    display:none;
    align-items:center;gap:12px;
    background:#fff;border:1px solid var(--line);
    border-radius:14px;padding:12px 16px;
  }
  .zoom-row.show{display:flex}
  .zoom-row label{font-size:.8rem;font-weight:600;color:var(--green);white-space:nowrap}
  input[type=range]{
    flex:1;appearance:none;height:6px;border-radius:3px;
    background:linear-gradient(90deg,var(--orange),var(--green));
    outline:none;
  }
  input[type=range]::-webkit-slider-thumb{
    appearance:none;width:26px;height:26px;border-radius:50%;
    background:#fff;border:3px solid var(--orange);
    box-shadow:0 2px 6px rgba(0,0,0,.2);cursor:grab;
  }
  footer{
    padding:0 16px 30px;text-align:center;
    font-size:.72rem;color:#8a9a8f;max-width:480px;
  }
  footer b{color:var(--green)}
  input[type=file]{display:none}
  @media (prefers-reduced-motion: reduce){*{transition:none!important}}
</style>
</head>
<body>

<header>
  <h1>URN <span>STUDIO</span></h1>
  <p>Créez votre affiche « J'adhère à l'URN » en 10 secondes</p>
</header>

<main>
  <div class="poster-wrap" id="wrap">
    <canvas id="cv" width="1254" height="1254"></canvas>
    <div class="hint" id="hint"><span>👆 Glissez pour positionner votre photo</span></div>
  </div>

  <div class="controls">
    <button class="btn btn-orange" id="pick">
      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="9" cy="9" r="2"/><path d="M21 15l-5-5L5 21"/></svg>
      Choisir ma photo
    </button>

    <div class="zoom-row" id="zoomRow">
      <label>Zoom</label>
      <input type="range" id="zoom" min="100" max="300" value="100">
    </div>

    <button class="btn btn-green" id="dl" disabled>
      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><path d="M7 10l5 5 5-5"/><path d="M12 15V3"/></svg>
      Télécharger mon affiche
    </button>
  </div>
</main>

<footer>
  Votre photo reste sur votre téléphone : rien n'est envoyé sur internet.<br>
  <b>Union pour le Réveil National</b> — Ensemble, réveillons les consciences.
</footer>

<input type="file" id="file" accept="image/*">

<script>
// ===== Template embarqué =====
const TEMPLATE_B64 = "";

// Ellipse du portrait dans le gabarit (mesurée au pixel près)
const E = { x0:27, y0:176, x1:612, y1:818 };
const ECX=(E.x0+E.x1)/2, ECY=(E.y0+E.y1)/2, ERX=(E.x1-E.x0)/2, ERY=(E.y1-E.y0)/2;

const cv = document.getElementById('cv');
const ctx = cv.getContext('2d');
const fileInput = document.getElementById('file');
const zoomEl = document.getElementById('zoom');
const dlBtn = document.getElementById('dl');
const hint = document.getElementById('hint');

const template = new Image();
template.src = "data:image/jpeg;base64," + TEMPLATE_B64;
template.onload = draw;

let photo = null;
let baseScale = 1;     // échelle "cover" de l'ellipse
let zoom = 1;          // multiplicateur utilisateur
let offX = 0, offY = 0; // décalage en px canvas

function draw(){
  ctx.clearRect(0,0,cv.width,cv.height);
  ctx.drawImage(template,0,0,cv.width,cv.height);
  if(!photo) return;
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(ECX,ECY,ERX,ERY,0,0,Math.PI*2);
  ctx.clip();
  const s = baseScale*zoom;
  const w = photo.width*s, h = photo.height*s;
  ctx.drawImage(photo, ECX - w/2 + offX, ECY - h/2 + offY, w, h);
  ctx.restore();
}

function loadPhoto(file){
  const url = URL.createObjectURL(file);
  const img = new Image();
  img.onload = () => {
    photo = img;
    // échelle minimale pour couvrir l'ellipse
    baseScale = Math.max((ERX*2)/img.width, (ERY*2)/img.height);
    zoom = 1.15; offX = 0; offY = -ERY*0.15; // léger recentrage vers le haut (visage)
    zoomEl.value = 115;
    document.getElementById('zoomRow').classList.add('show');
    dlBtn.disabled = false;
    hint.classList.add('show');
    setTimeout(()=>hint.classList.remove('show'), 3500);
    draw();
    URL.revokeObjectURL(url);
  };
  img.src = url;
}

document.getElementById('pick').onclick = () => fileInput.click();
fileInput.onchange = e => { if(e.target.files[0]) loadPhoto(e.target.files[0]); };

zoomEl.oninput = e => {
  if(!photo) return;
  zoom = e.target.value/100;
  clampOffset(); draw();
};

// limite le déplacement pour que la photo couvre toujours l'ellipse
function clampOffset(){
  const s = baseScale*zoom;
  const maxX = Math.max(0, photo.width*s/2 - ERX);
  const maxY = Math.max(0, photo.height*s/2 - ERY);
  offX = Math.min(maxX, Math.max(-maxX, offX));
  offY = Math.min(maxY, Math.max(-maxY, offY));
}

// ===== Drag (souris + tactile) + pinch zoom =====
let dragging = false, lastX=0, lastY=0, pinchDist=0, pinchZoom=1;
const wrap = document.getElementById('wrap');
const scaleFactor = () => cv.width / wrap.clientWidth;

wrap.addEventListener('pointerdown', e => {
  if(!photo || e.pointerType==='touch') return;
  dragging = true; lastX = e.clientX; lastY = e.clientY;
});
window.addEventListener('pointermove', e => {
  if(!dragging) return;
  const f = scaleFactor();
  offX += (e.clientX-lastX)*f; offY += (e.clientY-lastY)*f;
  lastX = e.clientX; lastY = e.clientY;
  clampOffset(); draw();
});
window.addEventListener('pointerup', ()=> dragging=false);

wrap.addEventListener('touchstart', e => {
  if(!photo) return;
  if(e.touches.length===1){ lastX=e.touches[0].clientX; lastY=e.touches[0].clientY; }
  else if(e.touches.length===2){
    pinchDist = Math.hypot(e.touches[0].clientX-e.touches[1].clientX, e.touches[0].clientY-e.touches[1].clientY);
    pinchZoom = zoom;
  }
}, {passive:true});

wrap.addEventListener('touchmove', e => {
  if(!photo) return;
  e.preventDefault();
  if(e.touches.length===1){
    const f = scaleFactor();
    offX += (e.touches[0].clientX-lastX)*f;
    offY += (e.touches[0].clientY-lastY)*f;
    lastX = e.touches[0].clientX; lastY = e.touches[0].clientY;
  } else if(e.touches.length===2){
    const d = Math.hypot(e.touches[0].clientX-e.touches[1].clientX, e.touches[0].clientY-e.touches[1].clientY);
    zoom = Math.min(3, Math.max(1, pinchZoom * d/pinchDist));
    zoomEl.value = Math.round(zoom*100);
  }
  clampOffset(); draw();
}, {passive:false});

// ===== Téléchargement =====
dlBtn.onclick = () => {
  cv.toBlob(blob => {
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'mon-affiche-URN.png';
    a.click();
    setTimeout(()=>URL.revokeObjectURL(a.href), 5000);
  }, 'image/png');
};

draw();
</script>
</body>
</html>
